from sys import stdin, stdout
for _ in range(int(stdin.readline())):
	n = int(stdin.readline())
	l = []
	departure = cnt = 0
	ans = float('inf')
	for i in range(n):
		(arr, dep) = list(map(int, stdin.readline().split()))
		l += [[arr, 1], [dep, -1]]
	l.sort(key=lambda x: (x[0], -x[1]))
	for (pt, type) in l:
		cnt += type
		if type == 1:
			if departure:
				ans = min(ans, cnt - 1)
		else:
			departure = 1
	print(ans if ans != float('inf') else -1)
